import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../theme/game_theme.dart';
import '../application/press_conference_provider.dart';
import '../domain/press_conference_engine.dart';
class PressConferenceDialog extends ConsumerWidget { const PressConferenceDialog({super.key});
@override Widget build(BuildContext context, WidgetRef ref) { final state = ref.watch(pressConferenceProvider); final actions = ref.read(pressConferenceProvider.notifier); return AlertDialog(backgroundColor: const Color(0xFF1C2541), title: const Text('POST-MATCH PRESS CONFERENCE', style: TextStyle(color: Colors.white, fontSize: 17, fontWeight: FontWeight.w900)), content: SingleChildScrollView(child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [const Text('Journalist: “Your bowling attack leaked 220 runs today. Do you regret resting your frontline spinner?”', style: TextStyle(color: Colors.white70, height: 1.5)), const SizedBox(height: 12), Text('TEAM CHEMISTRY  ${state.teamChemistry}/100', style: const TextStyle(color: GamePalette.gold, fontWeight: FontWeight.w900))])), actions: [TextButton(onPressed: () { actions.respond(response: MediaResponse.defendPlayer, strugglingPlayerIds: const ['Opener A'], bowlingUnitIds: const ['Fast Bowler A','Spinner B'], focalPlayerId: 'Spinner B'); Navigator.pop(context); }, child: const Text('DEFEND MY BOWLER', style: TextStyle(color: Colors.greenAccent))), TextButton(onPressed: () { actions.respond(response: MediaResponse.demandImprovement, strugglingPlayerIds: const ['Fast Bowler A','Spinner B'], bowlingUnitIds: const ['Fast Bowler A','Spinner B'], focalPlayerId: 'Spinner B'); Navigator.pop(context); }, child: const Text('DEMAND IMPROVEMENT', style: TextStyle(color: Colors.orangeAccent))), TextButton(onPressed: () { actions.respond(response: MediaResponse.acceptResponsibility, strugglingPlayerIds: const ['Fast Bowler A','Spinner B'], bowlingUnitIds: const ['Fast Bowler A','Spinner B'], focalPlayerId: 'Spinner B'); Navigator.pop(context); }, child: const Text('TAKE RESPONSIBILITY', style: TextStyle(color: Colors.white70)))]); }
}
Future<void> showPressConference(BuildContext context) => showDialog<void>(context: context, builder: (_) => const PressConferenceDialog());